import {useState,type FormEvent} from 'react'
import {Eye,EyeOff} from 'lucide-react'
import {ErrorNegocio} from '../../../shared/errorNegocio'
import {validarAcceso,type ErroresAcceso} from '../../../shared/validacionAcceso'
import {useAppData} from '../store/AppDataContext'
import {useNotificacion} from '../store/NotificacionContext'
import ModalAccesible from './ModalAccesible'
export default function CambiarPassword({onCerrar}:{onCerrar:()=>void}):React.JSX.Element{
 const {administrador,cambiarPassword}=useAppData(),{notificar}=useNotificacion()
 const [actual,setActual]=useState(''),[nueva,setNueva]=useState(''),[confirmar,setConfirmar]=useState(''),[error,setError]=useState(''),[ocupado,setOcupado]=useState(false)
 const [verActual,setVerActual]=useState(false),[verNueva,setVerNueva]=useState(false),[verConfirmar,setVerConfirmar]=useState(false)
 const [errores,setErrores]=useState<ErroresAcceso & {actual?:string}>({})
 async function guardar(event:FormEvent):Promise<void>{
  event.preventDefault();if(ocupado)return
  const campos={...validarAcceso({nombre:administrador,password:nueva,confirmar,codigo:'',modo:'crear'}),...(!actual?{actual:'Escribe tu contraseña actual.'}:{})}
  setErrores(campos);setError('');if(Object.keys(campos).length)return
  setOcupado(true)
  try{await cambiarPassword(actual,nueva);setActual('');setNueva('');setConfirmar('');notificar('exito','Contraseña actualizada.');onCerrar()}catch(e){setError(e instanceof ErrorNegocio?e.message:'No se pudo cambiar la contraseña.')}finally{setOcupado(false)}
 }
 const clase='w-full rounded-xl border border-[#dce5de] p-3 pr-12 text-sm'
 const campoPassword=(etiqueta:string,valor:string,setValor:(valor:string)=>void,visible:boolean,setVisible:(valor:boolean)=>void,autoComplete:string,autofocus=false):React.JSX.Element=><div className="relative mt-1"><input data-autofocus={autofocus||undefined} type={visible?'text':'password'} autoComplete={autoComplete} maxLength={128} value={valor} onChange={e=>setValor(e.target.value)} className={clase}/><button type="button" aria-label={visible?`Ocultar ${etiqueta}`:`Mostrar ${etiqueta}`} aria-pressed={visible} onClick={()=>setVisible(!visible)} className="absolute inset-y-0 right-0 flex w-12 items-center justify-center text-[#657069]">{visible?<EyeOff size={18}/>:<Eye size={18}/>}</button></div>
 return <ModalAccesible tituloId="cambiar-password-titulo" onCerrar={()=>{if(!ocupado)onCerrar()}} ancho="max-w-md">
  <h2 id="cambiar-password-titulo" className="font-bold">Cambiar contraseña</h2>
  <form noValidate onSubmit={guardar} className="mt-4 space-y-4">
   <label className="block text-sm">Contraseña actual{campoPassword('contraseña actual',actual,setActual,verActual,setVerActual,'current-password',true)}{errores.actual&&<span role="alert" className="text-xs text-[#9d3029]">{errores.actual}</span>}</label>
   <label className="block text-sm">Nueva contraseña{campoPassword('nueva contraseña',nueva,setNueva,verNueva,setVerNueva,'new-password')}{errores.password&&<span role="alert" className="text-xs text-[#9d3029]">{errores.password}</span>}</label>
   <label className="block text-sm">Confirmar nueva contraseña{campoPassword('confirmación de contraseña',confirmar,setConfirmar,verConfirmar,setVerConfirmar,'new-password')}{errores.confirmar&&<span role="alert" className="text-xs text-[#9d3029]">{errores.confirmar}</span>}</label>
   <p className="text-xs text-[#707972]">Usa entre 12 y 128 caracteres.</p>
   {error&&<p role="alert" className="text-sm text-[#9d3029]">{error}</p>}
   <div className="flex justify-end gap-3"><button type="button" disabled={ocupado} onClick={onCerrar} className="rounded-xl border p-3">Cancelar</button><button type="submit" disabled={ocupado} className="rounded-xl bg-[#16834b] p-3 text-white">Guardar contraseña</button></div>
  </form>
 </ModalAccesible>
}

import { useNotificacion } from '../store/NotificacionContext'
import { fechaLocal } from '../utils/reportes'
import { ErrorNegocio } from '../../../shared/errorNegocio'
import { useState, type FormEvent } from 'react'
import { Eye, EyeOff } from 'lucide-react'
import { useAppData } from '../store/AppDataContext'
import ModalAccesible from './ModalAccesible'
export default function ControlJornada(): React.JSX.Element {
  const { estadoJornada, fechaJornadaActiva, horaInicioJornada, gestionarJornada } = useAppData()
  const { notificar } = useNotificacion()
  const [accion, setAccion] = useState<'abrir' | 'cerrar' | 'reabrir' | null>(null)
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [ocupado, setOcupado] = useState(false)
  const [mostrarPassword, setMostrarPassword] = useState(false)
  const interrumpida = estadoJornada === 'interrumpida'
  const siguiente =
    estadoJornada === 'activa'
      ? 'cerrar'
      : interrumpida
        ? fechaJornadaActiva === fechaLocal()
          ? 'reabrir'
          : 'cerrar'
        : estadoJornada === 'finalizada'
          ? 'reabrir'
          : 'abrir'
  const etiquetas = {
    abrir: 'Iniciar jornada',
    cerrar: interrumpida ? 'Finalizar jornada interrumpida' : 'Finalizar jornada',
    reabrir: interrumpida ? 'Recuperar jornada de hoy' : 'Reabrir jornada de hoy'
  }
  async function guardar(e?: FormEvent, elegida = accion): Promise<void> {
    e?.preventDefault()
    if (!elegida || ocupado) return
    setOcupado(true)
    setError('')
    try {
      await gestionarJornada(elegida, elegida === 'reabrir' ? password : '')
      notificar('exito', elegida === 'abrir' ? 'Jornada iniciada correctamente.' : elegida === 'cerrar' ? 'Jornada finalizada correctamente.' : 'Jornada reabierta correctamente.')
      setAccion(null)
      setPassword('')
      setMostrarPassword(false)
    } catch (cause) {
      setError(cause instanceof ErrorNegocio ? cause.message : 'No se pudo actualizar la jornada.')
    } finally {
      setOcupado(false)
    }
  }
  return (
    <div className="mb-5 flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-[#e2e7e2] bg-white p-5">
      <div>
        <p className="text-sm font-bold text-[#176b3a]">
          {interrumpida
            ? `Jornada ${fechaJornadaActiva} interrumpida.`
            : estadoJornada === 'activa'
              ? `Jornada ${fechaJornadaActiva} activa desde ${horaInicioJornada}`
              : estadoJornada === 'finalizada'
                ? 'La jornada de hoy está cerrada'
                : 'No hay jornada activa'}
        </p>
      </div>
      <button
        type="button"
        onClick={() => {
          if (siguiente === 'abrir') void guardar(undefined, 'abrir')
          else setAccion(siguiente)
          setPassword('')
          setError('')
        }}
        disabled={ocupado}
        className={`rounded-xl px-5 py-3 text-sm font-semibold ${siguiente === 'cerrar' ? 'bg-[#c73737] text-white' : siguiente === 'reabrir' ? 'bg-[#f4bd43] text-[#523b09]' : 'bg-[#16834b] text-white'}`} 
      >
        {etiquetas[siguiente]}
      </button>
      {error && !accion && <p role="alert" className="text-sm text-[#9d3029]">{error}</p>}
      {accion && (
        <ModalAccesible
          tituloId="jornada-password"
          onCerrar={() => {
            if (!ocupado) {
              setAccion(null)
              setPassword('')
              setMostrarPassword(false)
            }
          }}
        >
          <h2 id="jornada-password" className="font-bold">
            {etiquetas[accion]}
          </h2>
          <form onSubmit={e => void guardar(e)} className="mt-4 space-y-4">
            {accion === 'cerrar' && <p>¿Seguro que deseas finalizar la jornada de hoy?</p>}
            {accion === 'reabrir' && <label className="block text-sm">
              Contraseña
              <div className="relative mt-2">
                <input
                  data-autofocus
                  required
                  type={mostrarPassword ? 'text' : 'password'}
                  autoComplete="current-password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full rounded-xl border p-3 pr-12"
                />
                <button
                  type="button"
                  aria-label={mostrarPassword ? 'Ocultar contraseña' : 'Mostrar contraseña'}
                  aria-pressed={mostrarPassword}
                  onClick={() => setMostrarPassword((visible) => !visible)}
                  className="absolute inset-y-0 right-0 flex w-12 items-center justify-center text-[#657069]"
                >
                  {mostrarPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </label>}
            {error && (
              <p role="alert" className="text-sm text-[#9d3029]">
                {error}
              </p>
            )}
            <div className="flex justify-end gap-3">
              <button
                type="button"
                disabled={ocupado}
                onClick={() => {
                  setAccion(null)
                  setPassword('')
                  setMostrarPassword(false)
                }}
                className="rounded-xl border px-4 py-2"
              >
                Cancelar
              </button>
              <button
                disabled={ocupado}
                type="submit"
                className="rounded-xl bg-[#16834b] px-4 py-2 text-white"
              >
                Confirmar
              </button>
            </div>
          </form>
        </ModalAccesible>
      )}
    </div>
  )
}

import ModalAccesible from './ModalAccesible'
import { useAppData, saldoDeCuenta } from '../store/AppDataContext'
import { formatoMoneda, formatoFecha } from '../utils/reportes'
import type { Cuenta } from '../types'

export default function DetalleCuenta({
  cuenta,
  onCerrar
}: {
  cuenta: Cuenta
  onCerrar: () => void
}): React.JSX.Element {
  const { movimientosCuenta, clientes, compras, ventas } = useAppData()
  const compra = cuenta.categoria === 'compra'
  const operacion = compra
    ? compras.find((c) => c.id === cuenta.compraId)
    : ventas.find((v) => v.id === cuenta.ventaId)
  const nombre = compra
    ? cuenta.proveedorNombre
    : clientes.find((c) => c.id === cuenta.clienteId)?.nombreRazonSocial
  const movimientos = movimientosCuenta
    .filter((m) => m.cuentaId === cuenta.id)
    .sort(
      (a, b) =>
        a.fecha.localeCompare(b.fecha) || a.fechaHoraRegistro.localeCompare(b.fechaHoraRegistro)
    )
  return (
    <ModalAccesible tituloId="detalle-cuenta" onCerrar={onCerrar} ancho="max-w-[850px]">
      <h2 id="detalle-cuenta" className="text-lg font-bold">
        {compra ? 'Compra' : 'Venta'} N.º {cuenta.numeroCompra ?? cuenta.numeroFactura ?? 'Manual'}{' '}
        · {nombre}
      </h2>
      <p className="my-3 text-sm">
        Fecha: {formatoFecha(cuenta.fecha)} · {operacion?.producto} · Estado: {cuenta.estado}
      </p>
      {operacion && (
        <div className="mb-3 rounded-xl bg-[#f5f7f4] p-3 text-sm">
          <p>
            Cantidad: {'cantidadQq' in operacion ? operacion.cantidadQq : operacion.pesoBruto} qq ·
            Precio/qq: $
            {formatoMoneda(
              'precioCompraQq' in operacion ? operacion.precioCompraQq : operacion.precioUnitario
            )}
          </p>
          <p>
            Subtotal: ${formatoMoneda(operacion.subtotal)} · Impuesto (
            {operacion.impuestoPorcentaje}%): ${formatoMoneda(operacion.montoImpuesto)}
          </p>
          <p>
            Observación:{' '}
            {('observacion' in operacion
              ? operacion.observacion
              : 'observaciones' in operacion
                ? operacion.observaciones
                : undefined) || '—'}
          </p>
          <p>Referencia: {cuenta.comprobante || '—'}</p>
        </div>
      )}
      <p className="mb-2 text-sm text-[#5b635e]">
        Registrado por: {cuenta.usuarioNombre ?? 'Sistema anterior'}
      </p>
      <p className="mb-3 text-sm">
        Total: ${formatoMoneda(cuenta.montoTotal)} · Aplicado a la cuenta: $
        {formatoMoneda(cuenta.montoPagado)} · Saldo: ${formatoMoneda(saldoDeCuenta(cuenta))}
      </p>
      <div className="overflow-x-auto">
        <table className="w-full text-left text-[12px]">
          <thead>
            <tr>
              {['Fecha', 'Movimiento', 'Monto', 'Método', 'Usuario', 'Observación / comprobante'].map((h) => (
                <th key={h} className="p-2">
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {movimientos.map((m) => (
              <tr key={m.id} className="border-t border-[#eef1ee]">
                <td className="p-2">{formatoFecha(m.fecha)}</td>
                <td className="p-2">{m.tipo}</td>
                <td className="p-2">${formatoMoneda(m.monto)}</td>
                <td className="p-2">
                  {m.metodoPago}
                  {m.metodoPago === 'Pago Mixto' && (
                    <div>
                      Efectivo: {formatoMoneda(m.montoEfectivo ?? 0)} · Transferencia:{' '}
                      {formatoMoneda(m.montoTransferencia ?? 0)}
                    </div>
                  )}
                </td>
                <td className="p-2">{m.usuarioNombre ?? 'Sistema anterior'}</td>
                <td className="p-2">
                  {m.observacion}
                  {m.comprobante && ' · ' + m.comprobante}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {!movimientos.length && <p className="my-4 text-sm">Todavía no hay pagos registrados.</p>}
      <button type="button" onClick={onCerrar} className="mt-5 rounded-xl border px-4 py-2">
        Cerrar
      </button>
    </ModalAccesible>
  )
}

import { ErrorNegocio } from '../../../shared/errorNegocio'
import { useId, useState, type FormEvent } from 'react'
import { Save, X } from 'lucide-react'
import { inputClass } from './FormField'
import ModalAccesible from './ModalAccesible'
import Toast from './Toast'
import { useToast } from '../hooks/useToast'
import { useAppData } from '../store/AppDataContext'
import { validarEmpleado } from '../utils/empleados'
import type { Empleado, EmpleadoFormData } from '../types'

interface Props {
  empleado?: Empleado | null
  onGuardado: (empleado: Empleado) => void
  onCancelar: () => void
}

export default function EmpleadoFormModal({
  empleado,
  onGuardado,
  onCancelar
}: Props): React.JSX.Element {
  const { empleados, crearEmpleado, actualizarEmpleado } = useAppData()
  const id = useId()
  const { aviso, notificar, cerrar } = useToast()
  const [form, setForm] = useState<EmpleadoFormData>(() =>
    empleado
      ? { ...empleado }
      : {
          nombre: '',
          cedula: '',
          telefono: '',
          direccion: '',
          estado: true
        }
  )
  const [tocados, setTocados] = useState<Partial<Record<keyof EmpleadoFormData, boolean>>>({})
  const [error, setError] = useState('')
  const datos = form
  const errores = validarEmpleado(datos, empleados, empleado?.id)
  const invalido = Object.keys(errores).length > 0

  function actualizar<K extends keyof EmpleadoFormData>(
    campo: K,
    valor: EmpleadoFormData[K]
  ): void {
    setForm((prev) => ({ ...prev, [campo]: valor }))
    setTocados((prev) => ({ ...prev, [campo]: true }))
    setError('')
    if (campo === 'cedula') {
      const errorCedula = validarEmpleado({ ...datos, [campo]: valor }, empleados, empleado?.id).cedula
      if (errorCedula === 'La cédula ya está registrada en el sistema') notificar(errorCedula, true)
    }
  }
  async function guardar(event: FormEvent): Promise<void> {
    event.preventDefault()
    event.stopPropagation()
    setTocados({ nombre: true, cedula: true, telefono: true, direccion: true, estado: true })
    if (invalido) return
    try {
      const resultado = empleado ? await actualizarEmpleado(empleado.id, datos) : await crearEmpleado(datos)
      onGuardado(resultado)
    } catch (cause) {
      const mensaje = cause instanceof ErrorNegocio ? cause.message : 'Error al procesar la operación'
      setError(mensaje)
      notificar(mensaje, true)
    }
  }
  function propiedades(campo: keyof EmpleadoFormData): {
    id: string
    'aria-invalid': boolean
    'aria-describedby': string | undefined
    className: string
  } {
    const visible = !!(tocados[campo] && errores[campo])
    return {
      id: `${id}-${campo}`,
      'aria-invalid': visible,
      'aria-describedby': visible ? `${id}-${campo}-error` : undefined,
      className: inputClass(visible)
    }
  }
  function mensaje(campo: keyof EmpleadoFormData): React.JSX.Element | null {
    return tocados[campo] && errores[campo] ? (
      <p id={`${id}-${campo}-error`} className="mt-1 text-[12px] text-[#9d3029]" aria-live="polite">
        {errores[campo]}
      </p>
    ) : null
  }
  const label = 'mb-1.5 block text-[12px] font-semibold text-[#4a524c]'
  return (
    <ModalAccesible
      tituloId={`${id}-titulo`}
      onCerrar={onCancelar}
      onKeyDown={(event) => {
        if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 's') {
          event.preventDefault()
          event.currentTarget.querySelector('form')?.requestSubmit()
        }
      }}
    >
      <div className="mb-5 flex items-center justify-between">
        <h2 id={`${id}-titulo`} className="text-[16px] font-bold">
          {empleado ? 'Editar Empleado' : 'Nuevo Empleado'}
        </h2>
        <button
          type="button"
          onClick={onCancelar}
          aria-label="Cerrar formulario de empleado"
          className="rounded-lg p-2 hover:bg-[#f0f4f0]"
        >
          <X size={18} />
        </button>
      </div>
      <form onSubmit={guardar} noValidate className="space-y-4">
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
          <div>
            <label htmlFor={`${id}-nombre`} className={label}>
              Nombre completo <span aria-hidden="true">*</span>
            </label>
            <input
              {...propiedades('nombre')}
              data-autofocus
              autoFocus
              required
              maxLength={100}
              value={form.nombre}
              onChange={(e) => actualizar('nombre', e.target.value)}
              placeholder="Ej: Juan Pérez García"
            />
            {mensaje('nombre')}
          </div>
          <div>
            <label htmlFor={`${id}-cedula`} className={label}>
              Cédula
            </label>
            <input
              {...propiedades('cedula')}
              inputMode="numeric"
              maxLength={20}
              value={form.cedula ?? ''}
              onChange={(e) => actualizar('cedula', e.target.value)}
              placeholder="Ej: 1234567890 (opcional)"
            />
            {mensaje('cedula')}
          </div>
          <div>
            <label htmlFor={`${id}-telefono`} className={label}>
              Teléfono
            </label>
            <input
              {...propiedades('telefono')}
              type="tel"
              maxLength={20}
              value={form.telefono ?? ''}
              onChange={(e) => actualizar('telefono', e.target.value)}
              placeholder="Ej: 0987654321"
            />
            {mensaje('telefono')}
          </div>
          <div className="sm:col-span-2">
            <label htmlFor={`${id}-direccion`} className={label}>
              Dirección
            </label>
            <textarea
              {...propiedades('direccion')}
              rows={2}
              maxLength={200}
              value={form.direccion ?? ''}
              onChange={(e) => actualizar('direccion', e.target.value)}
              placeholder="Dirección completa (opcional)"
            />
            {mensaje('direccion')}
          </div>
          <div>
            <span id={`${id}-estado-label`} className={label}>
              Estado
            </span>
            <button
              type="button"
              role="switch"
              aria-checked={form.estado}
              aria-labelledby={`${id}-estado-label ${id}-estado-texto`}
              onClick={() => actualizar('estado', !form.estado)}
              className="flex items-center gap-3 rounded-lg py-2 focus-visible:outline-2 focus-visible:outline-[#16834b]"
            >
              <span
                aria-hidden="true"
                className={`flex h-6 w-11 items-center rounded-full p-1 ${form.estado ? 'justify-end bg-[#16834b]' : 'justify-start bg-[#69736d]'}`}
              >
                <span className="h-4 w-4 rounded-full bg-white" />
              </span>
              <span id={`${id}-estado-texto`} className="text-[13px]">
                {form.estado ? 'Activo' : 'Inactivo'}
              </span>
            </button>
          </div>
        </div>
        {error && (
          <p role="alert" className="text-[13px] text-[#9d3029]">
            {error}
          </p>
        )}
        <div className="flex justify-end gap-3 border-t border-[#e2e7e2] pt-4">
          <button
            type="button"
            onClick={onCancelar}
            className="flex items-center gap-2 rounded-xl border border-[#e1e5e1] px-4 py-2.5 text-[13px] font-semibold"
          >
            <X size={16} />
            Cancelar
          </button>
          <button
            type="submit"
            disabled={invalido}
            className="flex items-center gap-2 rounded-xl bg-[#16834b] px-5 py-2.5 text-[13px] font-semibold text-white disabled:cursor-not-allowed disabled:opacity-50"
          >
            <Save size={16} />
            Guardar
          </button>
        </div>
        <p className="text-right text-[11px] text-[#5b635e]">
          Ctrl+S para guardar · Esc para cancelar
        </p>
      </form>
      <Toast aviso={aviso} onCerrar={cerrar} />
    </ModalAccesible>
  )
}

