import type { ReactNode } from 'react'

interface PageHeaderProps {
  greeting: string
  subtitle: string
  actions?: ReactNode
}

const today = new Date().toLocaleDateString('es-EC', {
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  year: 'numeric'
})

// Encabezado reutilizable para todas las páginas.
function PageHeader({ greeting, subtitle, actions }: PageHeaderProps): React.JSX.Element {
  return (
    <div className="mb-5 flex flex-col gap-4 sm:mb-6 sm:flex-row sm:items-center sm:justify-between">
      <div className="min-w-0">
        <p className="mb-1 text-[11px] font-medium capitalize text-[#8a938d] sm:text-[12px]">{today}</p>
        <h1 className="truncate text-[23px] font-bold tracking-[-0.6px] text-[#272c29] sm:text-[26px]">
          {greeting}
        </h1>
        <p className="mt-1 max-w-3xl text-[12px] leading-relaxed text-[#8a938d] sm:text-[13px]">
          {subtitle}
        </p>
      </div>

      {actions && <div className="flex flex-wrap items-center gap-2 sm:justify-end sm:gap-3">{actions}</div>}
    </div>
  )
}

export default PageHeader

import { useEffect, useId, useMemo, useState, type ReactNode } from 'react'
import { Plus, Search } from 'lucide-react'
import EmpleadoFormModal from './EmpleadoFormModal'
import { inputClass } from './FormField'
import { useAppData } from '../store/AppDataContext'
import { useNotificacion } from '../store/NotificacionContext'
import { coincideEmpleado, normalizarBusqueda } from '../utils/empleados'
import type { Empleado } from '../types'

interface Props {
  value?: number
  onChange: (id: number | undefined) => void
  error?: string
}

export default function SelectorEmpleado({ value, onChange, error }: Props): React.JSX.Element {
  const { empleados, empleadosActivos } = useAppData()
  const seleccionado = empleados.find((e) => e.id === value)
  const id = useId()
  const [texto, setTexto] = useState(seleccionado?.nombre ?? '')
  const [consulta, setConsulta] = useState('')
  const [abierto, setAbierto] = useState(false)
  const [activo, setActivo] = useState(-1)
  const [crear, setCrear] = useState(false)
  const { notificar } = useNotificacion()
  useEffect(() => {
    const timer = window.setTimeout(() => {
      setConsulta(texto)
      setActivo(-1)
    }, 200)
    return () => window.clearTimeout(timer)
  }, [texto])
  const buscando = texto !== consulta
  const resultados = useMemo(
    () =>
      consulta.trim().length < 2
        ? []
        : empleadosActivos
            .filter((empleado) => coincideEmpleado(empleado, consulta, false))
            .sort((a, b) => a.nombre.localeCompare(b.nombre, 'es')),
    [empleadosActivos, consulta]
  )
  const mostrarResultados = abierto && !buscando && consulta.trim().length >= 2
  useEffect(() => {
    if (activo >= 0)
      document.getElementById(`${id}-opcion-${activo}`)?.scrollIntoView({ block: 'nearest' })
  }, [activo, id])
  function seleccionar(empleado: Empleado): void {
    onChange(empleado.id)
    setTexto(empleado.nombre)
    setAbierto(false)
    setActivo(-1)
  }
  function resaltar(valor: string): ReactNode {
    const indice = normalizarBusqueda(valor).indexOf(normalizarBusqueda(consulta))
    if (indice < 0) return valor
    const fin = indice + consulta.trim().length
    return (
      <>
        {valor.slice(0, indice)}
        <mark className="rounded bg-[#fff0c9] text-inherit">{valor.slice(indice, fin)}</mark>
        {valor.slice(fin)}
      </>
    )
  }
  const opcionActiva =
    mostrarResultados && activo >= 0 && activo < resultados.length
      ? `${id}-opcion-${activo}`
      : undefined
  return (
    <div>
      <label
        htmlFor={`${id}-buscar`}
        className="mb-1.5 block text-[12px] font-semibold text-[#4a524c]"
      >
        Trabajador <span aria-hidden="true">*</span>
      </label>
      <div
        className="relative"
        onBlur={(event) => {
          if (!event.currentTarget.contains(event.relatedTarget)) setAbierto(false)
        }}
      >
        <div className="relative">
          <Search
            size={15}
            className="pointer-events-none absolute left-3 top-3.5 text-[#5b635e]"
            aria-hidden="true"
          />
          <input
            id={`${id}-buscar`}
            role="combobox"
            aria-autocomplete="list"
            aria-expanded={mostrarResultados}
            aria-controls={`${id}-lista`}
            aria-activedescendant={opcionActiva}
            aria-required="true"
            aria-invalid={!!error}
            aria-describedby={`${id}-ayuda${error ? ` ${id}-error` : ''}`}
            autoComplete="off"
            value={texto}
            placeholder="Escriba el nombre del trabajador..."
            className={inputClass(!!error) + ' pl-9'}
            onFocus={() => setAbierto(true)}
            onChange={(event) => {
              setTexto(event.target.value)
              onChange(undefined)
              setAbierto(true)
              setActivo(-1)
            }}
            onKeyDown={(event) => {
              if (event.key === 'Escape' && abierto) {
                event.preventDefault()
                event.stopPropagation()
                setAbierto(false)
                return
              }
              if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
                event.preventDefault()
                setAbierto(true)
                if (resultados.length && !buscando)
                  setActivo((prev) =>
                    event.key === 'ArrowDown'
                      ? Math.min(prev + 1, resultados.length - 1)
                      : Math.max(prev - 1, 0)
                  )
              }
              if (event.key === 'Enter' && abierto) {
                event.preventDefault()
                if (opcionActiva) seleccionar(resultados[activo])
              }
            }}
          />
        </div>
        {mostrarResultados && (
          <div
            id={`${id}-lista`}
            role="listbox"
            aria-label="Trabajadores activos"
            className="absolute z-10 mt-1 max-h-52 w-full overflow-y-auto rounded-xl border border-[#c3cfc5] bg-white py-1 shadow-lg"
          >
            {resultados.length === 0 ? (
              <p role="status" className="px-3 py-3 text-[12px] text-[#5b635e]">
                No se encontró al trabajador
              </p>
            ) : (
              resultados.map((empleado, indice) => (
                <div
                  key={empleado.id}
                  id={`${id}-opcion-${indice}`}
                  role="option"
                  aria-selected={activo === indice}
                  onMouseDown={(event) => event.preventDefault()}
                  onMouseMove={() => setActivo(indice)}
                  onClick={() => seleccionar(empleado)}
                  className={`flex cursor-pointer items-center gap-3 px-3 py-2 ${activo === indice ? 'bg-[#e7f2ea]' : 'hover:bg-[#f5f7f4]'}`}
                >
                  <span
                    aria-hidden="true"
                    className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-[#e7f2ea] text-[12px] font-bold text-[#176b3a]"
                  >
                    {empleado.nombre
                      .split(/\s+/)
                      .slice(0, 2)
                      .map((parte) => parte[0])
                      .join('')}
                  </span>
                  <span>
                    <span className="block text-[13px] font-semibold">
                      {resaltar(empleado.nombre)}
                    </span>
                    <span className="block text-[11px] text-[#4a524c]">
                      {empleado.cedula ? `Cédula: ${empleado.cedula}` : 'Sin cédula registrada'}
                    </span>
                  </span>
                </div>
              ))
            )}
          </div>
        )}
        <p id={`${id}-ayuda`} className="mt-1 text-[11px] text-[#5b635e]">
          {seleccionado
            ? `${seleccionado.nombre}${seleccionado.estado ? ' · Seleccionado' : ' · Inactivo (registro histórico)'}`
            : buscando
              ? 'Buscando…'
              : 'Escribe al menos 2 caracteres y selecciona un trabajador.'}
        </p>
        {error && (
          <p id={`${id}-error`} role="alert" className="mt-1 text-[12px] text-[#9d3029]">
            {error}
          </p>
        )}
        <button
          type="button"
          onClick={() => {
            setAbierto(false)
            setCrear(true)
          }}
          className="mt-2 flex items-center gap-1 rounded text-[12px] font-semibold text-[#176b3a] underline-offset-2 hover:underline"
        >
          <Plus size={14} />
          Registrar nuevo trabajador
        </button>
      </div>
      {crear && (
        <EmpleadoFormModal
          onCancelar={() => setCrear(false)}
          onGuardado={(empleado) => {
            setCrear(false)
            if (empleado.estado) {
              seleccionar(empleado)
              notificar('exito', 'Empleado registrado correctamente.')
            } else
              notificar('advertencia', 'Empleado registrado como inactivo. Actívalo para asignarlo a un gasto.')
          }}
        />
      )}
    </div>
  )
}

import { Menu } from 'lucide-react'
import { menuItems } from '../data/menu'
import type { Page } from '../types'
import { useAppData } from '../store/AppDataContext'
import logoGrupoRuiz from '../assets/brand/logo-grupo-ruiz.jpeg'

interface SidebarProps {
  activePage: Page
  onNavigate: (page: Page) => void
  collapsed: boolean
  onToggle: () => void
}

function Sidebar({ activePage, onNavigate, collapsed, onToggle }: SidebarProps): React.JSX.Element {
  const { usuarioActual } = useAppData()
  const items = menuItems.filter((item) => item.id !== 'usuarios' || usuarioActual?.rol === 'administrador')
  return (
    <aside
      className={[
        'flex h-screen shrink-0 flex-col border-r border-[#e4e8e4] bg-[#fbfcfb] transition-[width] duration-300 ease-in-out',
        collapsed ? 'w-[76px]' : 'w-[250px]'
      ].join(' ')}
    >
      {/* Cabecera: el único control para abrir/cerrar es el botón Menu. */}
      <div
        className={[
          'shrink-0 border-b border-[#e8ebe8]',
          collapsed
            ? 'flex flex-col items-center gap-2 px-2 py-3'
            : 'flex h-[82px] items-center justify-between px-5'
        ].join(' ')}
      >
        <div
          className={[
            'flex items-center',
            collapsed ? 'justify-center' : 'min-w-0 gap-3'
          ].join(' ')}
        >
          <div className="flex h-[46px] w-[46px] shrink-0 items-center justify-center overflow-hidden rounded-xl border border-[#e5e8e5] bg-white shadow-sm">
            <img src={logoGrupoRuiz} alt="Grupo Ruiz" className="h-full w-full object-contain" />
          </div>

          {!collapsed && (
            <div className="min-w-0">
              <h1 className="text-[19px] font-bold leading-tight tracking-[-0.5px] text-[#4b3428]">
                Ruiz<span className="text-[#176b3a]">Cacao</span>
              </h1>
              <p className="mt-1 text-[9px] font-semibold uppercase tracking-[1.4px] text-[#9a8a4f]">
                Grupo Ruiz
              </p>
            </div>
          )}
        </div>

        <button
          type="button"
          onClick={onToggle}
          title={collapsed ? 'Mostrar menú' : 'Ocultar menú'}
          aria-label={collapsed ? 'Mostrar menú' : 'Ocultar menú'}
          aria-expanded={!collapsed}
          className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg border border-transparent text-[#7c8680] transition-all duration-200 hover:border-[#dfe6df] hover:bg-white hover:text-[#176b3a]"
        >
          <Menu size={20} strokeWidth={1.8} />
        </button>
      </div>

      {/* Navegación: no cambia la lógica existente, solo su presentación. */}
      <div className={[
        'flex-1 overflow-y-auto py-6',
        collapsed ? 'px-2' : 'px-4'
      ].join(' ')}>
        {!collapsed && (
          <div className="mb-3 px-3">
            <span className="text-[10px] font-bold uppercase tracking-[1.2px] text-[#a3aaa5]">
              Menú principal
            </span>
          </div>
        )}

        <nav className="space-y-1.5">
          {items.map((item) => {
            const Icon = item.icon
            const isActive = activePage === item.id

            return (
              <button
                key={item.id}
                type="button"
                onClick={() => onNavigate(item.id)}
                title={collapsed ? item.label : undefined}
                aria-label={collapsed ? item.label : undefined}
                className={[
                  'group flex w-full items-center rounded-xl transition-all duration-200',
                  collapsed ? 'justify-center px-2 py-3' : 'gap-3 px-3 py-3 text-left',
                  isActive
                    ? 'bg-[#e7f2ea] text-[#176b3a] shadow-sm'
                    : 'text-[#66706a] hover:bg-[#f0f4f0] hover:text-[#176b3a]'
                ].join(' ')}
              >
                <span
                  className={[
                    'flex h-8 w-8 shrink-0 items-center justify-center rounded-lg transition-colors',
                    isActive
                      ? 'bg-white text-[#176b3a] shadow-sm'
                      : 'bg-transparent text-[#7d8780] group-hover:text-[#176b3a]'
                  ].join(' ')}
                >
                  <Icon size={17} strokeWidth={1.8} />
                </span>

                {!collapsed && (
                  <>
                    <span
                      className={[
                        'flex-1 truncate text-[13px]',
                        isActive ? 'font-semibold text-[#176b3a]' : 'font-medium'
                      ].join(' ')}
                    >
                      {item.label}
                    </span>
                    {isActive && <span className="h-2 w-2 shrink-0 rounded-full bg-[#d1a83f]" />}
                  </>
                )}
              </button>
            )
          })}
        </nav>
      </div>

    </aside>
  )
}

export default Sidebar

