          <PasswordFields
            password={password}
            confirmar={confirmar}
            mostrar={mostrar}
            setPassword={setPassword}
            setConfirmar={setConfirmar}
            setMostrar={setMostrar}
          />
          {error && <p className="mt-3 text-sm text-[#9d3029]">{error}</p>}
          <div className="mt-6 flex justify-end gap-3">
            <button
              type="button"
              onClick={() => {
                setResetId(null)
                resetearFormulario()
              }}
              className="rounded-xl border px-4 py-2.5"
            >
              Cancelar
            </button>
