import { createContext, useContext, useState, type ReactNode } from 'react'
import { CheckCircle2, AlertTriangle, XCircle } from 'lucide-react'

// ============================================================
// Reemplazo de window.alert() por un modal propio de la app.
//
// Por qué: window.alert() es un diálogo NATIVO del sistema operativo. En
// Electron, su título no es el <title> de index.html ni algo que se pueda
// personalizar desde el renderer — toma el nombre interno de la app
// (por eso aparecía "electron-app" en vez de "RuizCacao Manager"). Tampoco
// se le puede agregar un ícono de éxito/advertencia distinto al genérico
// del sistema.
//
// Con este modal propio, controlamos el título, el color y el ícono según
// el tipo de mensaje, y queda consistente con el resto de la identidad
// visual (verde/cacao/dorado) en vez de verse como una ventana de Windows.
// ============================================================

export type TipoNotificacion = 'exito' | 'advertencia' | 'error'

interface NotificacionState {
  tipo: TipoNotificacion
  mensaje: string
}

interface NotificacionContextValue {
  notificar: (tipo: TipoNotificacion, mensaje: string) => void
}

const NotificacionContext = createContext<NotificacionContextValue | null>(null)

const ESTILO_POR_TIPO: Record<
  TipoNotificacion,
  { icon: typeof CheckCircle2; iconoClase: string; fondoIcono: string; titulo: string }
> = {
  exito: {
    icon: CheckCircle2,
    iconoClase: 'text-[#16834b]',
    fondoIcono: 'bg-[#edf6ef]',
    titulo: 'RuizCacao Manager'
  },
  advertencia: {
    icon: AlertTriangle,
    iconoClase: 'text-[#9c7a1f]',
    fondoIcono: 'bg-[#fff0c9]',
    titulo: 'RuizCacao Manager'
  },
  error: {
    icon: XCircle,
    iconoClase: 'text-[#d64545]',
    fondoIcono: 'bg-[#fdeeee]',
    titulo: 'RuizCacao Manager'
  }
}

export function NotificacionProvider({ children }: { children: ReactNode }): React.JSX.Element {
  const [notificacion, setNotificacion] = useState<NotificacionState | null>(null)

  function notificar(tipo: TipoNotificacion, mensaje: string): void {
    setNotificacion({ tipo, mensaje })
  }

  const estilo = notificacion ? ESTILO_POR_TIPO[notificacion.tipo] : null
  const Icon = estilo?.icon

  return (
    <NotificacionContext.Provider value={{ notificar }}>
      {children}

      {notificacion && estilo && Icon && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/30 p-4">
          <div className="w-full max-w-[380px] rounded-2xl bg-white p-6 shadow-xl">
            <div className="mb-4 flex items-center gap-3">
              <div className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl ${estilo.fondoIcono} ${estilo.iconoClase}`}>
                <Icon size={20} />
              </div>
              <p className="text-[13px] font-bold text-[#272c29]">{estilo.titulo}</p>
            </div>
            <p className="mb-5 text-[13px] leading-relaxed text-[#4c534e]">{notificacion.mensaje}</p>
            <div className="flex justify-end">
              <button
                type="button"
                onClick={() => setNotificacion(null)}
                autoFocus
                className="rounded-xl bg-[#16834b] px-5 py-2.5 text-[13px] font-semibold text-white hover:bg-[#146b3e]"
              >
                Aceptar
              </button>
            </div>
          </div>
        </div>
      )}
    </NotificacionContext.Provider>
  )
}

export function useNotificacion(): NotificacionContextValue {
  const ctx = useContext(NotificacionContext)
  if (!ctx) throw new Error('useNotificacion debe usarse dentro de <NotificacionProvider>')
  return ctx
}

import { ErrorNegocio } from '../../../shared/errorNegocio'
import type { CompraInput, MetodoPago, Producto } from '../types'

export function redondearImporte(valor: number): number {
  return Math.round((valor + Number.EPSILON) * 100) / 100
}

export function calcularImportes(
  cantidad: number,
  precio: number,
  porcentaje: number
): {
  subtotal: number
  montoImpuesto: number
  total: number
} {
  const subtotal = redondearImporte(cantidad * precio)
  const montoImpuesto = redondearImporte((subtotal * porcentaje) / 100)
  return { subtotal, montoImpuesto, total: redondearImporte(subtotal + montoImpuesto) }
}

export function validarPago(
  total: number,
  pagado: number,
  metodo: MetodoPago,
  efectivo?: number,
  transferencia?: number
): void {
  if (!Number.isFinite(pagado) || pagado < 0 || redondearImporte(pagado) > total) {
    throw new ErrorNegocio('El pago debe estar entre 0 y el total de la operación.')
  }
  if (!['Efectivo', 'Transferencia', 'Pago Mixto'].includes(metodo))
    throw new ErrorNegocio('Método de pago no válido.')
  if (metodo === 'Pago Mixto') {
    if (![efectivo, transferencia].every((m) => m !== undefined && Number.isFinite(m) && m >= 0)) {
      throw new ErrorNegocio('Los importes de efectivo y transferencia deben ser válidos y no negativos.')
    }
    if (redondearImporte((efectivo ?? 0) + (transferencia ?? 0)) !== redondearImporte(pagado)) {
      throw new ErrorNegocio('Efectivo + transferencia debe coincidir con el pago registrado.')
    }
  }
}

export function validarCompra(input: CompraInput): ReturnType<typeof calcularImportes> {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(input.fecha)) throw new ErrorNegocio('Indica la fecha de compra.')
  if (!(['Cacao en Baba', 'Cacao Seco', 'Maracuyá'] as Producto[]).includes(input.producto))
    throw new ErrorNegocio('Producto no válido.')
  if (
    !Number.isFinite(input.cantidadQq) ||
    input.cantidadQq <= 0 ||
    !Number.isFinite(input.precioCompraQq) ||
    input.precioCompraQq <= 0
  ) {
    throw new ErrorNegocio('La cantidad y el precio deben ser mayores a cero.')
  }
  if (
    !Number.isFinite(input.impuestoPorcentaje) ||
    input.impuestoPorcentaje < 0 ||
    input.impuestoPorcentaje > 3
  ) {
    throw new ErrorNegocio('El impuesto debe estar entre 0% y 3%.')
  }
  const importes = calcularImportes(
    input.cantidadQq,
    input.precioCompraQq,
    input.impuestoPorcentaje
  )
  if (!Number.isFinite(importes.total) || importes.total <= 0)
    throw new ErrorNegocio('El total debe ser mayor a cero.')
  validarPago(
    importes.total,
    input.montoPagado,
    input.metodoPago,
    input.montoEfectivo,
    input.montoTransferencia
  )
  return importes
}

export function calcularConversion(
  babaDisponible: number,
  secoDisponible: number,
  babaUtilizada: number,
  factor: number
): {
  baba: number
  seco: number
  producido: number
} {
  if (!Number.isFinite(babaUtilizada) || babaUtilizada <= 0 || babaUtilizada > babaDisponible)
    throw new ErrorNegocio('La cantidad a convertir debe ser positiva y no superar la baba disponible.')
  if (!Number.isFinite(factor) || factor < 2.8 || factor > 5.3)
    throw new ErrorNegocio('El factor debe estar entre 2.8 y 5.3.')
  const producido = redondearImporte(babaUtilizada / factor)
  if (producido <= 0) throw new ErrorNegocio('La conversión debe producir al menos 0,01 qq de seco.')
  return {
    baba: redondearImporte(babaDisponible - babaUtilizada),
    seco: redondearImporte(secoDisponible + producido),
    producido
  }
}

